const database = require("../alphadata.js");
const path = require("path");
    // ...
let location = path.join(__dirname,"db","data");
    // ...
const db = new database(location);
    // ...
describe("Items",()=>{
  it("inserts items",()=>{
    for(let a = 1;a<=2;a++){
      for(let b = 1;b<=a*3;b++){
        db.select(`Test${a}`).insert({table:a,id:b});
      }
    }
    for(let a = 1;a<=2;a++){
      assert.equal(db.select(`Test${a}`).getSelected().length,a*3);
    }
  })
  it("deletes items",()=>{
    db.select("Test1").deleteItem();
    db.select("Test2").where((obj)=>{
      return(obj.id%2===0);
    }).deleteItem();
    assert.equal(db.select("Test1").getSelected().length,0);
    assert.equal(db.select("Test2").getSelected().length,3);
  })
  it("edits items",()=>{
    db.select("Test2").edit((obj)=>{
      obj.id = -1;
    });
    assert.equal(db.where((obj)=>obj.id === -1).getSelected().length,3);
  })
  it("gets items",()=>{
    db.initTables(["ItemGet","ItemGet2",{name:"ItemGet3",scheme:{
      data1:"string",
      data2:"number"
    }}]);
    for(let a = 0;a<10;a++){
      db.select("ItemGet").insert({id:a,num:Math.random()*a});
      db.select("ItemGet2").insert({table:"ItemGet2"})
    }
    assert.equal(db.select(()=>true).where((obj)=>{
      return(obj.id%2 === 0)
    }).getSelected().length,5);
    assert.equal(db.select("ItemGet2").getSelected().length,10);
    assert.equal(db.select((table)=>{
      return(table.indexOf("ItemGet")!=-1);
    }).getSelected().length,20);
    assert.equal(Object.keys(db.select("ItemGet").getSelected(["num"])[0]).length,1);
  })
  it("vertifies datatypes with schemes.",()=>{
    db.initTables([{name:"Scheme1",scheme:{
      data1:"string",
      data2:"number"
    }},
    {name:"Scheme2",scheme:{
      data1:"string",
      data2:"number"
    }},
   ])
    assert.throws(()=>{db.select("Scheme1").insert({data1:5,data2:"5"})},Error);
    assert.doesNotThrow(()=>{db.select("Scheme1").insert({data1:"5",data2:5})},Error);
  })
  db.write();
});

